import {projects,extras,initial,isPodcast,isEditing,isPhoto,priceLines,total,scopeText,narrative,reviewItems,change,restore} from './domain.mjs';
const $=s=>document.querySelector(s);
const money=n=>`N$ ${n.toLocaleString('en-NA')}`;
const escape=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const DRAFT='vh-configurator-v2';
let state=initial(),summaryOpen=false,priceChange='';
try{const stored=JSON.parse(localStorage.getItem(DRAFT));if(stored&&Date.now()-stored.savedAt<7*86400000)state=restore(stored.state)}catch{}
function save(){try{localStorage.setItem(DRAFT,JSON.stringify({savedAt:Date.now(),state}))}catch{/* Draft persistence is optional. */}}
function choose(key,value){
 const openDetails=[...document.querySelectorAll('details[open]')].map(el=>el.querySelector('summary').textContent);
 const before=total(state);state=change(state,key,value);const difference=total(state)-before;
 priceChange=difference?`${difference>0?'+':'−'}${money(Math.abs(difference))} · ${key==='extras'?'delivery updated':'setup updated'}`:'';
 render();document.querySelectorAll('details').forEach(el=>{el.open=openDetails.includes(el.querySelector('summary').textContent)});if(state.project)$('#price-announcement').textContent=`${scopeText(state)}. Illustrative estimate ${money(total(state))}.`;
}
function selectRow(key,value,description=''){return `<button class="selection-row ${state[key]===value?'selected':''}" data-key="${key}" data-value="${escape(value)}" aria-pressed="${state[key]===value}"><span>${escape(value)}${description?`<small>${description}</small>`:''}</span><span class="selection-mark" aria-hidden="true">${state[key]===value?'✓':'+'}</span></button>`}
function segments(key,values,suffix=''){return `<div class="segments">${values.map(v=>`<button data-key="${key}" data-value="${v}" aria-pressed="${state[key]===v}" class="${state[key]===v?'selected':''}">${v}${suffix}</button>`).join('')}</div>`}
function stepper(key,label,min,max){return `<div class="count-row"><span>${label}</span><div class="stepper"><button data-key="${key}" data-value="${state[key]-1}" aria-label="Fewer ${label.toLowerCase()}" ${state[key]<=min?'disabled':''}>−</button><output aria-label="${label}">${state[key]}</output><button data-key="${key}" data-value="${state[key]+1}" aria-label="More ${label.toLowerCase()}" ${state[key]>=max?'disabled':''}>+</button></div></div>`}
function podcastPlan(){return `<div class="podcast-plan" aria-label="${state.people} people and ${state.cameras} camera views"><div class="plan-people">${Array.from({length:state.people},(_,i)=>`<span class="person"><i aria-hidden="true"></i><small>${i===0?'Host':`Guest ${i}`}</small></span>`).join('')}</div><div class="plan-table"></div><div class="plan-views">${Array.from({length:state.cameras},(_,i)=>`<span class="view"><svg viewBox="0 0 32 24" aria-hidden="true"><rect x="2" y="4" width="20" height="16" rx="2"/><path d="m23 8 7-4v16l-7-4z"/></svg><small>${state.cameras===1?'Main view':i===0?'Wide view':`Close-up ${i}`}</small></span>`).join('')}</div><p>Your planned views · crew confirmed after review</p></div>`}
function serviceScreen(){return `<section class="service-screen"><p class="section-kicker">VISIONHAUS / PRODUCTION PLANNER</p><h1>What are we<br>making?</h1><p class="lead">Choose your starting point.</p><div class="service-choices">${['Video','Photo'].map((s,i)=>`<button class="service-main" data-key="service" data-value="${s}"><span class="service-number">0${i+1}</span><strong>${s==='Photo'?'Photography':'Video'}</strong><span class="service-caption">${i===0?'Stories in motion':'A moment, held'}</span><span class="service-arrow" aria-hidden="true">↗</span></button>`).join('')}</div><div class="service-secondary">${['Photo + video','Editing'].map(s=>`<button data-key="service" data-value="${s}"><span>${s}</span><span aria-hidden="true">↗</span></button>`).join('')}</div><p class="small-note">No account needed. Start with an idea.</p></section>`}
function projectScreen(){return `<p class="section-kicker">THE OUTCOME</p><h1>What’s the<br>project?</h1><div class="option-list">${projects[state.service].map(p=>selectRow('project',p)).join('')}</div>`}
function shootScreen(){
 if(isEditing(state))return `<p class="section-kicker">THE SOURCE</p><h1>Your footage.<br>Our next cut.</h1><p class="lead">We’ll review footage volume and final lengths before quoting.</p>${locationFields(false)}`;
 return `<p class="section-kicker">THE SHOOT</p><h1>${isPodcast(state)?'A conversation.<br>Your way.':'Shape your shoot.'}</h1>${isPodcast(state)?`<div class="question-block"><h2>Who’s in the conversation?</h2>${stepper('people','People',1,4)}${stepper('episodes','Episodes',1,6)}</div><div class="question-block"><h2>How should it feel?</h2><div class="option-list">${selectRow('framing','Direct to camera','One focused view')}${selectRow('framing','Conversation','Wide and close views')}${selectRow('framing','Full coverage','Wide view and two close-ups')}</div></div>${podcastPlan()}`:''}<div class="question-block"><h2>How much time on location?</h2>${segments('hours',[2,4,8],' hrs')}<p class="field-note">Total coverage time. Setup and crew need review.</p></div>${locationFields(true)}${!isPhoto(state)?`<details class="advanced"><summary>Fine-tune camera views <span>Optional</span></summary><div class="question-block"><h3>Camera angles</h3>${segments('cameras',[1,2,3])}<p class="field-note">Camera views do not determine operator count.</p></div></details>`:''}`;
}
function locationFields(show){
 const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Africa/Windhoek',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
 return `<div class="field-grid">${show?`<label>Where are we shooting?<select id="location">${['Windhoek','Swakopmund','Walvis Bay','Other / remote'].map(l=>`<option ${state.location===l?'selected':''}>${l}</option>`).join('')}</select></label>`:''}<label>${show?'Preferred date':'Preferred delivery date'}<input id="date" type="date" min="${today}" value="${escape(state.date)}"><small>Leave blank if flexible</small></label></div>`;
}
function deliveryScreen(){return `<p class="section-kicker">THE DELIVERY</p><h1>${isPhoto(state)?'The finishing<br>touches.':'More from<br>your shoot.'}</h1><p class="lead">${isPhoto(state)?'Photo post-production is included.':'Your main edit is included.'}</p><div class="option-list">${extras.filter(e=>!isPhoto(state)||e.id==='rush').map(e=>`<button class="selection-row ${state.extras.includes(e.id)?'selected':''}" data-extra="${e.id}" aria-pressed="${state.extras.includes(e.id)}"><span>${e.title}<small>${e.description}</small></span><span class="extra-price">+${money(e.price)}</span><span class="selection-mark" aria-hidden="true">${state.extras.includes(e.id)?'✓':'+'}</span></button>`).join('')}</div><p class="field-note">Exact lengths, revisions and delivery date are confirmed in your quote.</p>`}
function lineItems(){return `<div class="receipt-lines">${priceLines(state).map(l=>`<div><span>${l.label}</span><span>${money(l.amount)}</span></div>`).join('')}</div>`}
function reviewScreen(){return `<p class="section-kicker">YOUR PRODUCTION</p><h1>Here’s the plan.</h1><p class="review-narrative">${escape(narrative(state))}</p><div class="review-total"><span>Illustrative estimate · ex VAT</span><strong>${money(total(state))}</strong></div><p class="field-note">Excludes unresolved production and travel costs. This is not a quotation.</p><details class="advanced"><summary>View the details</summary>${lineItems()}</details><form id="contact" class="contact"><h2>Who are we creating for?</h2><div class="field-grid"><label>Your name<input id="name" name="name" autocomplete="name" maxlength="100" required value="${escape(state.name)}"></label><label>Email address<input id="email" name="email" type="email" autocomplete="email" required maxlength="150" value="${escape(state.email)}"></label></div></form><p class="demo-note">Demo only. Your brief stays on this device. Nothing is sent.</p>`}
const canContinue=()=>Boolean(state.project);
const nextLabel=()=>state.section==='review'?'Save demo brief':state.section==='delivery'?'Review your plan':state.section==='shoot'?'Choose delivery':'Shape your shoot';
function summaryBody(mobile=false){return `<p class="section-kicker">YOUR PRODUCTION</p><h2>${escape(state.project||state.service)}</h2><p class="scope-description">${escape(state.project?narrative(state):'Choose your project to start shaping the scope.')}</p><div class="summary-facts"><span>${isEditing(state)?'Footage review':escape(state.location)}</span><span>${state.date?escape(state.date):'Date flexible'}</span></div>${state.project?`<div class="receipt-total"><span>Illustrative estimate</span><strong>${money(total(state))}</strong><small>Ex VAT · final quotation follows review</small></div><p class="price-change" aria-hidden="true">${priceChange||'&nbsp;'}</p><details class="price-details"><summary>Price breakdown</summary>${lineItems()}</details><div class="review-needed"><span class="neutral-label">Needs review</span><ul>${reviewItems(state).map(i=>`<li>${i}</li>`).join('')}</ul></div>`:'<p class="field-note">Your estimate appears after you choose a project.</p>'}${mobile?'':`<button class="primary" data-next ${!canContinue()?'disabled':''}>${nextLabel()} <span aria-hidden="true">↗</span></button><p class="demo-note">Preview prices. No booking is submitted.</p>`}`}
function completeScreen(){return `<section class="completion"><p class="section-kicker">DEMO COMPLETE</p><h1>Your plan<br>is ready.</h1><p class="review-narrative">${escape(narrative(state))}</p><p class="lead">Saved on this device. Nothing has been sent.</p><button class="primary" id="download">Download demo brief <span>↗</span></button><button class="quiet" id="edit-plan">Return to your plan</button></section>`}
function renderControls(){
 const root=$('#control-surface');if(!state.service||state.complete){root.innerHTML='';return}
 root.innerHTML=`<div class="mobile-controls">${summaryOpen?`<section class="mobile-summary" id="mobile-summary" aria-label="Production summary">${summaryBody(true)}</section>`:''}<div class="control-row"><button class="summary-trigger" id="summary-toggle" aria-expanded="${summaryOpen}" aria-controls="mobile-summary"><span class="mobile-scope">${escape(scopeText(state))}</span><span class="mobile-total">${state.project?money(total(state)):'Choose your project'} <small>${state.project?'ex VAT · demo':''}</small><i aria-hidden="true">${summaryOpen?'⌄':'⌃'}</i></span></button><button class="primary" data-next ${!canContinue()?'disabled':''}>${state.section==='review'?'Save demo':'Continue'} <span aria-hidden="true">↗</span></button></div></div>`;
 $('#summary-toggle').onclick=()=>{summaryOpen=!summaryOpen;renderControls();bindNext();$('#summary-toggle').focus({preventScroll:true})};
}
function render(){
 save();
 if(state.complete)$('#app').innerHTML=completeScreen();
 else if(!state.service)$('#app').innerHTML=serviceScreen();
 else $('#app').innerHTML=`<div class="workspace-header"><button class="service-switch" id="change-service">← ${escape(state.service)}</button><span class="saved-label">DRAFT ON THIS DEVICE</span></div><div class="workspace"><div class="canvas"><nav class="section-nav" aria-label="Production sections">${[['project','Project'],['shoot',isEditing(state)?'Footage':'Shoot'],['delivery','Delivery'],['review','Review']].map(([key,label])=>`<button data-section="${key}" ${key!=='project'&&!state.project?'disabled':''} ${key===state.section?'aria-current="page"':''}>${label}</button>`).join('')}</nav><section class="task" id="task">${({project:projectScreen,shoot:shootScreen,delivery:deliveryScreen,review:reviewScreen})[state.section]()}</section></div><aside class="receipt" aria-label="Running production summary">${summaryBody()}</aside></div>`;
 renderControls();bindEvents();
}
function bindNext(){document.querySelectorAll('[data-next]').forEach(b=>b.onclick=next)}
function next(){
 if(!canContinue())return;
 if(state.section==='review'){
  if(!$('#contact').reportValidity()){summaryOpen=false;renderControls();bindNext();return}
  state.complete=true;
 }else state.section=({project:'shoot',shoot:'delivery',delivery:'review'})[state.section];
 summaryOpen=false;render();focusTask();
}
function focusTask(){const h=$('#task h1')||$('h1');if(h){h.setAttribute('tabindex','-1');h.focus({preventScroll:true})}scrollTo({top:0})}
function bindEvents(){
 document.querySelectorAll('[data-key]').forEach(b=>b.onclick=()=>{const label=b.getAttribute('aria-label');const key=b.dataset.key,value=['people','episodes','hours','cameras'].includes(key)?Number(b.dataset.value):b.dataset.value;choose(key,value);[...document.querySelectorAll('[data-key]')].find(x=>label?x.getAttribute('aria-label')===label:x.dataset.key===key&&x.dataset.value===String(value))?.focus({preventScroll:true})});
 document.querySelectorAll('[data-section]').forEach(b=>b.onclick=()=>{state.section=b.dataset.section;summaryOpen=false;render();focusTask()});
 document.querySelectorAll('[data-extra]').forEach(b=>b.onclick=()=>{const id=b.dataset.extra;choose('extras',state.extras.includes(id)?state.extras.filter(x=>x!==id):[...state.extras,id]);document.querySelector(`[data-extra="${id}"]`)?.focus({preventScroll:true})});
 for(const id of['date','location'])if($('#'+id))$('#'+id).onchange=e=>{choose(id,e.target.value);$('#'+id)?.focus({preventScroll:true})};
 for(const id of['name','email'])if($('#'+id))$('#'+id).oninput=e=>{state[id]=e.target.value;save()};
 if($('#contact'))$('#contact').onsubmit=e=>{e.preventDefault();next()};
 if($('#change-service'))$('#change-service').onclick=()=>{state={...state,service:'',project:'',section:'project'};summaryOpen=false;render();focusTask()};
 if($('#edit-plan'))$('#edit-plan').onclick=()=>{state.complete=false;render();focusTask()};
 if($('#download'))$('#download').onclick=download;
 bindNext();
}
function download(){const blob=new Blob([JSON.stringify({notice:'Demo only. Not submitted. Illustrative prices.',brief:state,estimate:priceLines(state),total:total(state)},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='visionhaus-demo-brief.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('#reset').onclick=()=>{if(confirm('Clear this draft and start again?')){state=initial();summaryOpen=false;priceChange='';render();focusTask()}};
render();
if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{/* Online use remains available. */});
